Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='sealedwordsstay', at=datetime(2026, 10, 25, 0, 0, 0), actor='assistant', title='Sealed words, the store registry, the trust registry and the prefetch budget stay in Suzatary', body="Sealed words, their keys and their erasure stay in Suzatary and do not move to the Prodrome. So do the store registry with its tiers, the trust registry that says which key may sign for which actor, and a device's prefetch budget. The Prodrome rewrites no object and says nothing about secrecy, so it holds no keys. Sealed words move only when a second program needs them.", rationale="Where data may go and who may sign for whom are this deployment's policy, and a library that held keys would take on key custody and a threat model.", supersedes=()))